// Phantom-order reconciliation. Proposes deletions; NEVER deletes.
//
// REFERENCE IMPLEMENTATION: scripts/reconcile_phantom_orders.py. That version has the
// test suite (tests/test_reconcile_abort_rails.py, 8 tests covering every abort rail) and
// is the source of truth for this logic. If you change the rails here, change them there
// and re-run the tests -- silent drift between the two is the main risk with this node.
//
// Abort rails: any one of these throws, which aborts the run BEFORE anything is written
// and triggers the Sync Error Handler -> #tech-alerts-sos. Aborting must always beat
// guessing: a timed-out chunk or a stalled sync is indistinguishable, at this point in the
// code, from "Backoffice deleted everything".
const API_BASE = 'https://qtml5qv6uk.execute-api.eu-central-1.amazonaws.com/production';
const API_KEY = 'BACKOFFICE_API_KEY_PLACEHOLDER';
const SUPA = 'https://ybznbfezrdgzgptxkgul.supabase.co';
const SUPA_KEY = 'SUPABASE_SERVICE_KEY';

const WINDOW_DAYS = 45;
const SKIP_RECENT_DAYS = 2;   // same-day indexing lag, BACKOFFICE_API_ISSUES.md #13
const MAX_TRIES = 6;
const BASE_BACKOFF_MS = 1000;
const MAX_CANDIDATES = 50;
// Raised 5.0 -> 10.0 on 2026-09-02, only because rail 2a below now exists. The real August
// incident (34 phantoms / 681 rows) came in at 4.993% and cleared the old ceiling by
// 0.007pp. Keep in step with scripts/reconcile_phantom_orders.py.
const MAX_CANDIDATE_PCT = 10.0;
const ORDER_SYNC_WORKFLOWS = ['orders-hot', 'orders-warm', 'orders-cool', 'backfill'];

// --- Order transform: mirrors scripts/order_transform.py, which in turn mirrors the
// `Transform Orders` node in orders-{hot,warm,cool}.json. Three copies is two too many, but
// the repair direction must write rows IDENTICAL to what the normal sync writes, or repaired
// rows would look like drift on the next run. If you change one, change all three;
// tests/test_order_transform.py pins the behaviours that have actually bitten us.
const ASUNTOSAATIO_EXCL_VAT_EUR = 400;
const ASUNTOSAATIO_INCL_VAT_EUR = 502;

function tsToIso(val) {
  if (val === null || val === undefined || val === '' || val === 0) return null;
  // `-` in the first 10 chars, not a bare 4-digit check: an epoch like "1779599528" has
  // leading digits that look like a year and silently produced an invalid timestamp.
  if (typeof val === 'string' && (val.includes('T') || val.slice(0, 10).includes('-'))) return val;
  const n = parseFloat(val);
  if (isNaN(n)) return null;
  return new Date(n * 1000).toISOString();
}

// Charge amounts are integer cents for most orders but decimal euros for a real cohort
// (~20% of recent platform orders), with no distinguishing flag -- issue #2.
function parseChargeAmountCents(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(v);
  if (isNaN(n)) return null;
  return Number.isInteger(n) ? Math.round(n) : Math.round(n * 100);
}

function parseManualTotal(charge) {
  if (!charge || charge.charge === null || charge.charge === undefined || charge.charge === '') {
    return { eur: null, cents: null, raw: null };
  }
  const raw = String(charge.charge).trim();
  const cleaned = raw.replace(/ /g, '').replace(/€/g, '').replace(/EUR/gi, '')
                     .replace(/\s/g, '').replace(',', '.');
  if (!/^[-+]?\d+(\.\d+)?$/.test(cleaned)) return { eur: null, cents: null, raw };
  const eur = parseFloat(cleaned);
  return { eur, cents: Math.round(eur * 100), raw };
}

function transformOrder(d) {
  if (!d || !d.orderId) return null;
  const isManual = d.isManual === true || d.isManual === 'true' ||
    (d.customer !== undefined && d.additionalInfo !== undefined);
  const charge = d.charge || {};

  let manualData = null;
  let isAsuntosaatio = 'No';
  if (isManual) {
    const pricing = parseManualTotal(charge);
    let mentions = false;
    try { mentions = JSON.stringify(d).toLowerCase().includes('asuntosäätiö'); } catch (e) { mentions = false; }
    const override = mentions && pricing.eur === 0;
    isAsuntosaatio = override ? 'Yes' : 'No';
    manualData = {
      customer: d.customer || null,
      additionalInfo: d.additionalInfo || null,
      serviceFeeApplied: d.serviceFeeApplied || null,
      total_incl_vat_eur: override ? ASUNTOSAATIO_INCL_VAT_EUR : pricing.eur,
      total_incl_vat_cents: override ? ASUNTOSAATIO_INCL_VAT_EUR * 100 : pricing.cents,
      total_excl_vat_eur: override ? ASUNTOSAATIO_EXCL_VAT_EUR : null,
      total_excl_vat_cents: override ? ASUNTOSAATIO_EXCL_VAT_EUR * 100 : null,
      price_basis: 'gross_incl_vat',
      raw_charge_total: pricing.raw,
      original_total_incl_vat_eur: override ? pricing.eur : undefined,
      value_override_reason: override ? 'asuntosaatio_b2b_flat_rate' : undefined,
    };
  }

  const base = isManual ? null : parseChargeAmountCents(charge.basePrice);
  const services = isManual ? null : parseChargeAmountCents(charge.servicesPrice);
  const recycling = isManual ? null : parseChargeAmountCents(charge.recyclingSurcharge);
  const platformFee = isManual ? null : parseChargeAmountCents(charge.platformFee);
  const serviceFee = isManual ? null : parseChargeAmountCents(charge.serviceFee);
  const totalExclVat = (!isManual && base !== null && platformFee !== null)
    ? base + platformFee + (services || 0) + (recycling || 0) : null;

  return {
    order_id: d.orderId,
    is_manual: isManual,
    created_at: tsToIso(d.created || d.createdAt),
    organization_name: d.organizationName || null,
    org_id: d.orgId || null,
    hub_id: d.hubId || null,
    order_state: d.orderState || null,
    order_type: d.orderType || null,
    origin: isManual ? null : (d.origin || null),
    first_schedule: tsToIso(d.firstSchedule),
    schedule: d.schedule || null,
    content: d.content || null,
    stops: d.stops || null,
    charge: d.charge || null,
    platform_fee: platformFee,
    service_fee: serviceFee,
    base_price_cents: base,
    services_price_cents: services,
    recycling_surcharge_cents: recycling,
    total_excl_vat_cents: totalExclVat,
    route_id: d.routeId || null,
    commission_rate: d.commissionRate !== undefined && d.commissionRate !== null ? parseFloat(d.commissionRate) : null,
    underway_at: tsToIso(d.underwayAt),
    in_transit_at: tsToIso(d.inTransitAt),
    delivered_at: tsToIso(d.deliveredAt),
    review: d.review || null,
    manual_data: manualData,
    is_asuntosaatio_gig: isAsuntosaatio,
    synced_at: new Date().toISOString(),
  };
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const isoDay = (d) => d.toISOString().slice(0, 10);

async function supaGet(path) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPA}/rest/v1/${path}`,
    headers: { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}` },
    json: true,
  });
}

// Day-by-day, never multi-day: 30-day /order windows fail ~47% of the time with 500/504
// (BACKOFFICE_API_ISSUES.md #7).
async function liveOrdersForDay(day) {
  const orders = new Map();
  const endpoints = [
    // includeUnscheduled=true REQUIRED here, or ~96 real orders/window look deleted (#12)
    { path: 'order', extra: '&includeUnscheduled=true' },
    // ...and must NOT be sent to /manual-order, which 400s on it (docs/GOTCHAS.md)
    { path: 'manual-order', extra: '' },
  ];
  for (const ep of endpoints) {
    let ok = false;
    let lastErr = null;
    for (let attempt = 1; attempt <= MAX_TRIES; attempt++) {
      try {
        const data = await this.helpers.httpRequest({
          method: 'GET',
          url: `${API_BASE}/${ep.path}?start_date=${day}&end_date=${day}${ep.extra}`,
          headers: { 'x-api-key': API_KEY },
          json: true,
        });
        if (!Array.isArray(data)) throw new Error('unexpected response shape');
        for (const o of data) if (o && o.orderId) orders.set(o.orderId, o);
        ok = true;
        break;
      } catch (e) {
        lastErr = e;
        if (attempt < MAX_TRIES) await sleep(BASE_BACKOFF_MS * Math.pow(2, attempt - 1));
      }
    }
    if (!ok) {
      throw new Error(
        `ABORT RAIL 1: /${ep.path} for ${day} failed after ${MAX_TRIES} tries ` +
        `(${lastErr && lastErr.message}). A day we cannot read is indistinguishable from ` +
        `a day where everything was deleted -- refusing to propose any candidates.`
      );
    }
  }
  return orders;
}

const today = new Date();
const end = new Date(today); end.setUTCDate(end.getUTCDate() - SKIP_RECENT_DAYS);
const start = new Date(end); start.setUTCDate(start.getUTCDate() - (WINDOW_DAYS - 1));

// --- Rail 3: is the pipeline healthy enough for its output to be trusted at all? ---
// Ordered by completed_at, NOT started_at: started_at is NULL on every order-sync row in
// sync_log (verified live 2026-09-02).
const wfFilter = ORDER_SYNC_WORKFLOWS.map((w) => `"${w}"`).join(',');
const runs = await supaGet.call(
  this,
  `sync_log?workflow=in.(${wfFilter})&status=eq.success` +
  `&completed_at=gte.${isoDay(start)}T00:00:00Z` +
  `&select=workflow,completed_at&order=completed_at.desc&limit=1`
);
if (!runs || runs.length === 0) {
  throw new Error(
    `ABORT RAIL 3: no successful order-sync run in sync_log since ${isoDay(start)}. ` +
    `If the pipeline itself is stalled we have no business proposing deletions.`
  );
}
const ageH = (Date.now() - new Date(runs[0].completed_at).getTime()) / 3600000;
if (ageH > 24) {
  throw new Error(
    `ABORT RAIL 3: most recent successful order-sync completed ${ageH.toFixed(1)}h ago ` +
    `(${runs[0].completed_at}). Pipeline looks stalled -- refusing to propose deletions.`
  );
}

const candidates = [];
const repairs = [];
let totalSupaRows = 0;
for (let d = new Date(start); d <= end; d.setUTCDate(d.getUTCDate() + 1)) {
  const day = isoDay(d);
  const live = await liveOrdersForDay.call(this, day);
  const liveIds = new Set(live.keys());

  const nxt = new Date(d); nxt.setUTCDate(nxt.getUTCDate() + 1);
  // No order_state filter on either side: a CANCELLED order still exists upstream and is
  // still returned by /order, so it is not a phantom.
  const rows = await supaGet.call(
    this,
    `orders?created_at=gte.${day}T00:00:00Z&created_at=lt.${isoDay(nxt)}T00:00:00Z` +
    `&select=order_id,created_at,is_manual,order_state,organization_name,hub_id,` +
    `total_excl_vat_cents,synced_at`
  );
  totalSupaRows += rows.length;

  // --- Rail 2a: a whole day wiped out ---
  // An empty-but-successful (HTTP 200 `[]`) response is not a retryable error, so rail 1
  // never sees it -- yet it makes every Supabase row for that day look deleted. Checked
  // per-day, not in aggregate: on a 45-day window one wiped day is a small overall
  // percentage and would slip under the proportional rail below.
  if (rows.length > 0 && live.size === 0) {
    throw new Error(
      `ABORT RAIL 2a: ${day} returned ZERO order ids upstream while Supabase holds ` +
      `${rows.length} rows for that day. An empty-but-successful API response is ` +
      `indistinguishable from that day being deleted wholesale -- refusing to propose ` +
      `${rows.length} deletions off it. Nothing written.`
    );
  }

  // --- Direction 2: present upstream, missing here -> repair immediately ---
  // Additive and non-destructive, so no approval gate: re-adding a row that provably exists
  // upstream cannot lose data, and requiring a click would recreate the exact failure this
  // catches (one May 2026 order sat missing for three months because nothing watched this
  // direction). Deliberately NOT volume-capped -- if Supabase lost rows, re-adding them all
  // is the correct response. Transform mirrors scripts/order_transform.py.
  const supaIds = new Set(rows.map((r) => r.order_id));
  for (const [oid, o] of live) {
    if (!supaIds.has(oid)) repairs.push(transformOrder(o));
  }

  for (const r of rows) {
    if (!liveIds.has(r.order_id)) {
      candidates.push({
        order_id: r.order_id,
        created_at: r.created_at,
        status: 'pending',
        evidence: {
          reason: 'present_in_supabase_absent_upstream',
          checked_day: day,
          live_api_ids_that_day: liveIds.size,
          supabase_rows_that_day: rows.length,
          order: {
            created_at: r.created_at, is_manual: r.is_manual, order_state: r.order_state,
            organization_name: r.organization_name, hub_id: r.hub_id,
            total_excl_vat_cents: r.total_excl_vat_cents, synced_at: r.synced_at,
          },
          endpoints_checked: ['/order?includeUnscheduled=true', '/manual-order'],
          detected_by: 'n8n orders-reconcile',
        },
      });
    }
  }
}

// --- Rail 2: volume sanity, evaluated before anything is written ---
const pct = totalSupaRows ? (candidates.length / totalSupaRows) * 100 : 0;
if (candidates.length > MAX_CANDIDATES) {
  throw new Error(
    `ABORT RAIL 2b: ${candidates.length} candidates exceeds the ${MAX_CANDIDATES}-row ` +
    `ceiling -- treating as a data-source failure, not a mass deletion. Nothing written.`
  );
}
if (pct > MAX_CANDIDATE_PCT) {
  throw new Error(
    `ABORT RAIL 2b: candidates are ${pct.toFixed(1)}% of the ${totalSupaRows}-row window, ` +
    `over the ${MAX_CANDIDATE_PCT}% ceiling. Nothing written.`
  );
}

return [{ json: {
  candidates,
  repairs,
  stats: {
    window_start: isoDay(start), window_end: isoDay(end),
    days_checked: WINDOW_DAYS, supabase_rows_in_window: totalSupaRows,
    candidates: candidates.length, candidate_pct: Number(pct.toFixed(3)),
    repairs: repairs.length,
  },
} }];

// One item per candidate so the Upsert node can post them as a batch. Emits nothing when
// there are no candidates -- the IF node routes that case straight to Log Sync.
const c = $json.candidates || [];
return c.map((x) => ({ json: x }));

// One item per repaired order. Emits nothing when there is no drift in this direction,
// which is the expected steady state once parity is reached.
const r = $('Reconcile').first().json.repairs || [];
return r.filter(Boolean).map((x) => ({ json: x }));
